import { ChangeDetectorRef, Component, ElementRef, EventEmitter, HostListener, Output, QueryList, ViewChild, ViewChildren } from '@angular/core';
import { ProfileComponent } from '../../profile/profile.component';
import { IconComponent } from '../../icon/icon.component';
import { MatRippleModule } from '@angular/material/core';
import { ActiveSubModule, FaqList, InsertFeedbackReq, KeyWordList, ModuleList } from '../../../interfaces/helpcenter.interface';
import { UserDetail } from '../../../../core/interfaces/login.interface';
import { environment } from '../../../../../environments/environment';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { Router } from '@angular/router';
import { HelpcenterService } from '../../../services/helpcenter/helpcenter.service';
import { MatDialog } from '@angular/material/dialog';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { AssistanceComponent } from '../../assistance/assistance.component';
import { NgClass } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { style, transition } from '@angular/animations';
import { trigger } from '@angular/animations';
import { animate } from '@angular/animations';

@Component({
  selector: 'helpcenterview',
  standalone: true,
  imports: [ProfileComponent, IconComponent, MatRippleModule, NgClass, FormsModule],
  templateUrl: './helpcenterview.component.html',
  styleUrl: './helpcenterview.component.scss',
  animations: [
    trigger('fadeInOut', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(-10px)' }),
        animate(
          '300ms ease-out',
          style({ opacity: 1, transform: 'translateY(0)' })
        ),
      ]),
      transition(':leave', [
        animate(
          '300ms ease-in',
          style({ opacity: 0, transform: 'translateY(-10px)' })
        ),
      ]),
    ]),
  ]
})
export class HelpcenterviewComponent {
  @ViewChildren('optionRef') optionRefs!: QueryList<ElementRef>;
  @ViewChild('parent') parent: ElementRef;
  @Output() selectedsubmodule = new EventEmitter<any>();

  selectedIndex: number = -1;
  @HostListener('window:keydown', ['$event'])
  handleKeyDown(event: KeyboardEvent): void {
    if (this.keyWords.length === 0) return;

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        this.selectedIndex = this.selectedIndex < this.keyWords.length - 1 
          ? this.selectedIndex + 1 
          : 0;
        this.scrollToOption();
        break;

      case 'ArrowUp':
        event.preventDefault();
        this.selectedIndex = this.selectedIndex > 0 
          ? this.selectedIndex - 1 
          : this.keyWords.length - 1;
        this.scrollToOption();
        break;

      case 'Enter':
        event.preventDefault();
        if (this.selectedIndex >= 0) {
          this.keyWordClick(this.keyWords[this.selectedIndex]);
        }
        break;
    }
  }

  private scrollToOption(): void {
    requestAnimationFrame(() => {
      const element = this.optionRefs.get(this.selectedIndex)?.nativeElement;
      if (element) {
        element.scrollIntoView({ block: 'nearest' });
      }
    });
  }


  cQType: string = 'S';
  searchterm: string = '';

  activemodule: ActiveSubModule | null = null;

  userdetail: UserDetail;
  showfaq: boolean = true;


  typewriterText: string = ''; // Text shown in the input
  placeholders: string[] = [
    'Access and edit case files ?',
    'Comparing ?',
    'navigating?',
    'transcript'
  ];
  currentPlaceholderIndex: number = 0;

  commonTopics: KeyWordList[] = [];

  moduleList: ModuleList[] = [];

  faq: FaqList[] = [];

  keyWords: KeyWordList[] = [];

  selectedKeywordId = 0;

  helpcenterURL = `${environment.documentStorage}${environment.helpcenterPath}help/`;


  constructor(
    private ss: SecureStorageService,
    private router: Router,
    private dialog: MatDialog,
    private helpcenterService: HelpcenterService,
    private cdr: ChangeDetectorRef,
    private cf: CommonfunctionService
  ) { }

  async ngOnInit() {
    this.apiCall();
    this.userdetail = await this.ss.getUserInfo();
    this.startTypewriterEffect();
  }

  apiCall() {
    this.getCommonTopics();
    this.getModuleList();
    this.getfaqlist();
  }

  startTypewriterEffect() {
    let currentText = '';
    const placeholder = this.placeholders[this.currentPlaceholderIndex];
    let charIndex = 0;

    const type = () => {
      if (charIndex < placeholder.length) {
        currentText += placeholder[charIndex];
        this.typewriterText = currentText;
        charIndex++;
        setTimeout(type, 100); // Adjust typing speed
      } else {
        // Pause before erasing
        setTimeout(this.eraseText.bind(this), 2000); // Wait 2 seconds before erasing
      }
    };

    const erase = () => {
      if (currentText.length > 0) {
        currentText = currentText.slice(0, -1);
        this.typewriterText = currentText;
        setTimeout(erase, 25); // Adjust erasing speed
      } else {
        // Move to the next placeholder
        this.currentPlaceholderIndex =
          (this.currentPlaceholderIndex + 1) % this.placeholders.length;
        setTimeout(this.startTypewriterEffect.bind(this), 50); // Wait before typing new text
      }
    };

    this.eraseText = erase;
    type();
  }

  eraseText() { }


  goToAdmin() {
    this.router.navigate(['/admin/dashboard']);
  }

  async selectmodule(x) {

    if (!this.activemodule) {
      this.activemodule = {} as ActiveSubModule;
    }

    if (this.activemodule['id'] == x.nMainid) {
      return;
    }

    this.activemodule['id'] = x.nMainid;
    const res = await this.helpcenterService.getSubModuleList(x.nMainid);
    this.activemodule['submodules'] = res;
  }

  expand(elm) {
    // Check if elm is already expanded
    const isCurrentlyExpanded = elm.isexpand;

    // Collapse all elements
    this.faq.forEach((x) => {
      x.isexpand = false;
    });

    // If elm was not already expanded, expand it
    if (!isCurrentlyExpanded) {
      elm.isexpand = true;
    }
  }


  assist() {
    const dialog = this.dialog.open(AssistanceComponent, {
      width: '500px',
      height: 'fit-content',
    });
    dialog.afterClosed().subscribe((result) => {
    })
  }

  async getCommonTopics() {
    this.commonTopics = await this.helpcenterService.getCommonTopics();
    this.cdr.detectChanges();
  }

  async getModuleList(nKeyid?: number) {
    this.moduleList = await this.helpcenterService.getModuleList(nKeyid);
    this.activemodule = null;
    if (this.moduleList.length > 0 && nKeyid) {
      // this.searchterm='';
      this.keyWords = [];
    }
    this.cdr.detectChanges();
  }

  async getfaqlist() {
    this.faq = await this.helpcenterService.getfaqlist(this.cQType);
    this.cdr.detectChanges();
  }

  async insertFeedback(data: InsertFeedbackReq) {
    await this.helpcenterService.insertFeedback(data);
  }

  async getkeywords(key: string) {
    return await this.helpcenterService.getkeywords(key);
  }

  async search(event: string) {
    if (event.length > 2) {
      this.keyWords = await this.getkeywords(event);
      this.cdr.detectChanges();
    }
  }


  clearList() {
    this.searchterm = '';
    this.keyWords = [];
  }

  keyWordClick(item: KeyWordList) {
    // this.searchterm = item.cTitle;
    // const link = document.createElement("a");
    // link.href = item.cLink;
    // link.target = "_blank"; // Opens in a new tab
    // document.body.appendChild(link);
    // link.click();
    // document.body.removeChild(link);
    // this.selectedsubmodule.emit(item);
    this.openNewTab(item);



    try {
      this.helpcenterService.searchSMid(item.nSMid)
    } catch (error) {

    }
    this.cdr.detectChanges();
  }

  openNewTab(x) {
    const param1 = this.activemodule?.id;
    const param2 = x.nSMid;

    // Construct the URL dynamically
    const url = this.router.serializeUrl(
      this.router.createUrlTree(['/helpcenterdetail', 'help'], { queryParams: { id: param1, nSMid: param2 } })
    );

    // Open in a new tab
    window.open(url, '_blank');
  }

  gotofaq() {
    this.showfaq = true;
    const faq = document.getElementById('faq');
    if (faq) {
      let top = faq.offsetTop;
      this.parent.nativeElement.scrollTo({
        top: top,
        behavior: 'smooth'
      });
    }
  }
}
