import { ChangeDetectorRef, Component } from '@angular/core';
import { MatSelectModule } from '@angular/material/select';
import { TextareaComponent } from '../textarea/textarea.component';
import { ButtonComponent } from '../button/button.component';
import { IconComponent } from '../icon/icon.component';
import { MatDialog, MatDialogRef } from '@angular/material/dialog';
import { TicketService } from '../../services/ticket/ticket.service';
import { caselistRes } from '../../interfaces/ticket.interface';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-assistance',
  standalone: true,
  imports: [FormsModule, MatSelectModule, TextareaComponent, ButtonComponent, IconComponent],
  templateUrl: './assistance.component.html',
  styleUrl: './assistance.component.scss'
})
export class AssistanceComponent {
  success: boolean = false
  uploadlength: number = 0;
  cSessionid: string = '';
  nCaseid: string;
  caselist: caselistRes[] = [];
  isSubmitted: boolean = false;
  cDesc: string = '';
  cImage: string;
  cImagename: string;
  constructor(private MatDialogRef: MatDialogRef<AssistanceComponent>, private ticketS: TicketService,
    private cdr: ChangeDetectorRef
  ) {
    this.cSessionid = Math.floor((Math.random() * 10000000000) + 1).toString();
  }

  ngOnInit() {
    // this.cSessionid = this.generateRandomString()
    this.getAssignedCase();
  }

  close() {
    this.MatDialogRef.close();
  }

  generateRandomString(length = 12) {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    let result = '';
    for (let i = 0; i < length; i++) {
      result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return result;
  }

  async getAssignedCase() {
    this.caselist = await this.ticketS.getCaseList()
  }



  getFile() {
    const fileInput: any = document.querySelector('#ticketimage');
    fileInput.click();
  }

  async onFileChange(e) {
    if (!e.target.files[0]) return;
    const formData = new FormData();
    formData.append('file', e.target.files[0]);
    var filename = e.target.files[0].name;
    const res = await this.ticketS.moduleimageUpload(formData);
    if (res?.msg == 1) {
      this.uploadlength = 1;
      this.cImage = res.value;
      this.cImagename = filename;
    }
    let fileInput = document.getElementById('ticketimage') as HTMLInputElement;
    if (fileInput) {
      fileInput.value = ''; // Clears the input field
    }
    this.cdr.detectChanges();
  }

  submitTicket() {
    debugger;
    if (!this.nCaseid || !this.cDesc || this.cDesc == '') {
      this.isSubmitted = true;
    }
    else {
      this.isSubmitted = false;
      this.ticketS.submitTicket(this.nCaseid, this.cSessionid, this.cDesc, this.cImage, this.cImagename).then((res) => {
        if (res) {
          this.success = true;
          setTimeout(() => {
            this.MatDialogRef.close();
          }, 3000);
        }
      })
    }
  }

}
