import { Component } from '@angular/core';
import { trigger, transition, style, animate } from '@angular/animations';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { HelpcenterviewComponent } from './helpcenterview/helpcenterview.component';
import { ProfileComponent } from '../profile/profile.component';
import { UserDetail } from '../../../core/interfaces/login.interface';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { HelpcenterdetailComponent } from './helpcenterdetail/helpcenterdetail.component';
import { NgClass } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import { HelpcenterService } from '../../services/helpcenter/helpcenter.service';
@Component({
  selector: 'app-helpcenter',
  standalone: true,
  imports: [HelpcenterviewComponent, ProfileComponent, HelpcenterdetailComponent, NgClass],
  templateUrl: './helpcenter.component.html',
  styleUrl: './helpcenter.component.scss',
 
})
export class HelpcenterComponent {
  constructor(private cf: CommonfunctionService, private ss: SecureStorageService, private route: ActivatedRoute, private helpcenterService: HelpcenterService) {
   
  }

  userdetail: UserDetail;
  selectedsubmodule: any;


  async ngOnInit() {
    this.userdetail = await this.ss.getUserInfo();
  }



  goToHome() {
    this.cf.goto('user/dashboard');
  }


  selectedsubmoduleEvent(item: any) {
    this.selectedsubmodule = item;
  }
}
